//! Command-line interface definition and parsing.

pub mod fraction;
pub mod quantity;
pub mod threads;

use crate::bytes_format::BytesFormat;
use clap::{builder::PossibleValue, Arg, ArgAction, ArgMatches, Command};
use fraction::Fraction;
use quantity::Quantity;
use std::{ffi::OsString, num::NonZeroU64, path::PathBuf};
use threads::Threads;

/// Maximum depth to display, either infinite or a positive integer.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MaxDepth {
    Infinite,
    Finite(NonZeroU64),
}

impl MaxDepth {
    /// Parse from the raw string given on the command line.
    pub fn parse(text: &str) -> Result<Self, String> {
        let text = text.trim();
        if text == "inf" {
            return Ok(MaxDepth::Infinite);
        }
        text.parse::<NonZeroU64>()
            .map(MaxDepth::Finite)
            .map_err(|error| format!("Value is neither \"inf\" nor a positive integer: {error}"))
    }

    /// Convert to a number, treating infinity as the maximum value.
    pub fn as_u64(self) -> u64 {
        match self {
            MaxDepth::Infinite => u64::MAX,
            MaxDepth::Finite(value) => value.get(),
        }
    }
}

/// Width configuration of the chart.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ColumnWidth {
    /// Width of the whole chart.
    Total(usize),
    /// Maximum width of the tree column and exact width of the bar column.
    Components { tree: usize, bar: usize },
}

/// Parsed command-line arguments.
#[derive(Debug, Clone)]
pub struct Args {
    pub files: Vec<PathBuf>,
    pub json_input: bool,
    pub json_output: bool,
    pub bytes_format: BytesFormat,
    pub deduplicate_hardlinks: bool,
    pub top_down: bool,
    pub align_right: bool,
    pub quantity: Quantity,
    pub max_depth: MaxDepth,
    pub column_width: Option<ColumnWidth>,
    pub min_ratio: Fraction,
    pub no_sort: bool,
    pub silent_errors: bool,
    pub progress: bool,
    pub threads: Threads,
    pub omit_json_shared_details: bool,
    pub omit_json_shared_summary: bool,
}

const SHORT_EXAMPLES: &str = "\
Examples:
    $ pdu
    $ pdu path/to/file/or/directory
    $ pdu file.txt dir/
    $ pdu --quantity=apparent-size
    $ pdu --deduplicate-hardlinks
    $ pdu --bytes-format=plain
    $ pdu --bytes-format=binary
    $ pdu --min-ratio=0
    $ pdu --min-ratio=0.05
    $ pdu --min-ratio=0 --max-depth=inf --json-output | jq
    $ pdu --json-input < disk-usage.json
";

const LONG_EXAMPLES: &str = "\
Examples:
    Show disk usage chart of current working directory
    $ pdu

    Show disk usage chart of a single file or directory
    $ pdu path/to/file/or/directory

    Compare disk usages of multiple files and/or directories
    $ pdu file.txt dir/

    Show chart in apparent sizes instead of block sizes
    $ pdu --quantity=apparent-size

    Detect and subtract the sizes of hardlinks from their parent nodes
    $ pdu --deduplicate-hardlinks

    Show sizes in plain numbers instead of metric units
    $ pdu --bytes-format=plain

    Show sizes in base 2¹⁰ units (binary) instead of base 10³ units (metric)
    $ pdu --bytes-format=binary

    Show disk usage chart of all entries regardless of size
    $ pdu --min-ratio=0

    Only show disk usage chart of entries whose size is at least 5% of total
    $ pdu --min-ratio=0.05

    Show disk usage data as JSON instead of chart
    $ pdu --min-ratio=0 --max-depth=inf --json-output | jq

    Visualize existing JSON representation of disk usage data
    $ pdu --json-input < disk-usage.json
