Copyright: Apache-2.0 © 2021 Hoàng Văn Khải <https://github.com/KSXGitHub/>
Sponsor: https://github.com/sponsors/KSXGitHub";

/// Build the clap command.
pub fn command() -> Command {
    Command::new("pdu")
        .version("0.21.1")
        .about(ABOUT)
        .long_about(LONG_ABOUT)
        .after_help(SHORT_EXAMPLES)
        .after_long_help(LONG_EXAMPLES)
        .term_width(0)
        .arg(
            Arg::new("files")
                .value_name("FILES")
                .num_args(0..)
                .value_parser(clap::value_parser!(PathBuf))
                .help("List of files and/or directories"),
        )
        .arg(
            Arg::new("json-input")
                .long("json-input")
                .action(ArgAction::SetTrue)
                .conflicts_with_all(["quantity", "deduplicate-hardlinks"])
                .help("Read JSON data from stdin"),
        )
        .arg(
            Arg::new("json-output")
                .long("json-output")
                .action(ArgAction::SetTrue)
                .help("Print JSON data instead of an ASCII chart"),
        )
        .arg(
            Arg::new("bytes-format")
                .short('b')
                .long("bytes-format")
                .value_name("BYTES_FORMAT")
                .default_value("metric")
                .value_parser([
                    PossibleValue::new("plain").help("Display plain number of bytes without units"),
                    PossibleValue::new("metric")
                        .help("Use metric scale, i.e. 1K = 1000B, 1M = 1000K, and so on"),
                    PossibleValue::new("binary")
                        .help("Use binary scale, i.e. 1K = 1024B, 1M = 1024K, and so on"),
                ])
                .help("How to display the numbers of bytes"),
        )
        .arg(
            Arg::new("deduplicate-hardlinks")
                .short('H')
                .long("deduplicate-hardlinks")
                .visible_aliases(["detect-links", "dedupe-links"])
                .action(ArgAction::SetTrue)
                .help("Detect and subtract the sizes of hardlinks from their parent directory totals"),
        )
        .arg(
            Arg::new("top-down")
                .long("top-down")
                .action(ArgAction::SetTrue)
                .help("Print the tree top-down instead of bottom-up"),
        )
        .arg(
            Arg::new("align-right")
                .long("align-right")
                .action(ArgAction::SetTrue)
                .help("Set the root of the bars to the right"),
        )
        .arg(
            Arg::new("quantity")
                .short('q')
                .long("quantity")
                .value_name("QUANTITY")
                .default_value("block-size")
                .value_parser([
                    PossibleValue::new("apparent-size").help("Measure apparent sizes"),
                    PossibleValue::new("block-size").help("Measure block sizes (block-count * 512B)"),
                    PossibleValue::new("block-count").help("Count numbers of blocks"),
                ])
                .help("Aspect of the files/directories to be measured"),
