        .arg(
            Arg::new("max-depth")
                .short('d')
                .long("max-depth")
                .visible_alias("depth")
                .value_name("MAX_DEPTH")
                .default_value("10")
                .value_parser(MaxDepth::parse)
                .help("Maximum depth to display the data. Could be either \"inf\" or a positive integer"),
