                .short('w')
                .long("total-width")
                .visible_alias("width")
                .value_name("TOTAL_WIDTH")
                .conflicts_with("column-width")
                .value_parser(clap::value_parser!(usize))
                .help("Width of the visualization"),
        )
        .arg(
            Arg::new("column-width")
                .long("column-width")
                .value_names(["TREE_WIDTH", "BAR_WIDTH"])
                .num_args(2)
                .value_parser(clap::value_parser!(usize))
                .help("Maximum widths of the tree column and width of the bar column"),
        )
        .arg(
            Arg::new("min-ratio")
                .short('m')
                .long("min-ratio")
                .value_name("MIN_RATIO")
                .default_value("0.01")
                .value_parser(Fraction::parse)
                .help("Minimal size proportion required to appear"),
        )
        .arg(
            Arg::new("no-sort")
                .long("no-sort")
                .action(ArgAction::SetTrue)
                .help("Do not sort the branches in the tree"),
        )
        .arg(
            Arg::new("silent-errors")
                .short('s')
                .long("silent-errors")
                .visible_alias("no-errors")
                .action(ArgAction::SetTrue)
                .help("Prevent filesystem error messages from appearing in stderr"),
        )
        .arg(
            Arg::new("progress")
                .short('p')
                .long("progress")
                .action(ArgAction::SetTrue)
                .help("Report progress being made at the expense of performance"),
        )
        .arg(
            Arg::new("threads")
                .long("threads")
                .value_name("THREADS")
                .default_value("auto")
                .value_parser(Threads::parse)
                .help("Set the maximum number of threads to spawn. Could be either \"auto\", \"max\", or a positive integer"),
        )
        .arg(
            Arg::new("omit-json-shared-details")
                .long("omit-json-shared-details")
                .action(ArgAction::SetTrue)
                .requires_all(["json-output", "deduplicate-hardlinks"])
                .help("Do not output `.shared.details` in the JSON output"),
        )
        .arg(
            Arg::new("omit-json-shared-summary")
                .long("omit-json-shared-summary")
                .action(ArgAction::SetTrue)
                .requires_all(["json-output", "deduplicate-hardlinks"])
                .help("Do not output `.shared.summary` in the JSON output"),
        )
}

impl Args {
    /// Parse the process arguments.
    pub fn parse() -> Self {
        Self::from_iter(std::env::args_os())
    }

    /// Parse from an iterator of arguments.
    pub fn from_iter<I>(iter: I) -> Self
    where
        I: IntoIterator,
        I::Item: Into<OsString> + Clone,
    {
        let matches = command().get_matches_from(iter);
        Self::from_matches(&matches)
    }

    fn from_matches(matches: &ArgMatches) -> Self {
        let files = matches
            .get_many::<PathBuf>("files")
            .map(|values| values.cloned().collect())
            .unwrap_or_default();
        let bytes_format = match matches.get_one::<String>("bytes-format").map(String::as_str) {
            Some("plain") => BytesFormat::Plain,
            Some("binary") => BytesFormat::Binary,
            _ => BytesFormat::Metric,
        };
        let quantity = match matches.get_one::<String>("quantity").map(String::as_str) {
            Some("apparent-size") => Quantity::ApparentSize,
            Some("block-count") => Quantity::BlockCount,
            _ => Quantity::BlockSize,
        };
        let column_width = if let Some(total) = matches.get_one::<usize>("total-width") {
            Some(ColumnWidth::Total(*total))
        } else if let Some(mut values) = matches.get_many::<usize>("column-width") {
            let tree = *values.next().expect("tree width");
            let bar = *values.next().expect("bar width");
            Some(ColumnWidth::Components { tree, bar })
        } else {
            None
        };
        Args {
            files,
            json_input: matches.get_flag("json-input"),
            json_output: matches.get_flag("json-output"),
            bytes_format,
            deduplicate_hardlinks: matches.get_flag("deduplicate-hardlinks"),
            top_down: matches.get_flag("top-down"),
            align_right: matches.get_flag("align-right"),
            quantity,
            max_depth: *matches.get_one::<MaxDepth>("max-depth").expect("max depth has a default"),
            column_width,
            min_ratio: *matches.get_one::<Fraction>("min-ratio").expect("min ratio has a default"),
            no_sort: matches.get_flag("no-sort"),
            silent_errors: matches.get_flag("silent-errors"),
            progress: matches.get_flag("progress"),
            threads: *matches.get_one::<Threads>("threads").expect("threads has a default"),
            omit_json_shared_details: matches.get_flag("omit-json-shared-details"),
            omit_json_shared_summary: matches.get_flag("omit-json-shared-summary"),
        }
    }
}
