//! Floating-point value in the range `[0, 1)`.

use std::str::FromStr;

/// A ratio that is at least 0 and strictly less than 1.
#[derive(Debug, Clone, Copy, PartialEq, PartialOrd)]
pub struct Fraction(f32);

impl Fraction {
    /// Validate and wrap a float.
    pub fn new(value: f32) -> Result<Self, &'static str> {
        if value < 0.0 {
            return Err("less than 0");
        }
        if value >= 1.0 {
            return Err("greater than or equal to 1");
        }
        Ok(Fraction(value))
    }

    /// Parse from the raw string given on the command line.
    pub fn parse(text: &str) -> Result<Self, String> {
        let value: f32 = text.parse().map_err(|error| format!("{error}"))?;
        Fraction::new(value).map_err(String::from)
    }

    /// Get the inner float.
    pub fn get(self) -> f32 {
        self.0
    }
}

impl FromStr for Fraction {
    type Err = String;
    fn from_str(text: &str) -> Result<Self, Self::Err> {
        Fraction::parse(text)
    }
}
