//! Formatting of byte counts.

use std::fmt::{self, Display, Formatter};

/// How to display numbers of bytes.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BytesFormat {
    /// Plain number without units.
    Plain,
    /// Powers of 1000.
    Metric,
    /// Powers of 1024.
    Binary,
}

const UNITS: [char; 5] = ['K', 'M', 'G', 'T', 'P'];

/// Result of formatting a byte count, ready to be displayed.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum FormattedBytes {
    /// Just a number.
    Plain(u64),
    /// A number without unit, padded to align with scaled numbers.
    Unscaled(u64),
    /// A scaled number with unit.
    Scaled(f64, char),
}

impl Display for FormattedBytes {
    fn fmt(&self, formatter: &mut Formatter<'_>) -> fmt::Result {
        match self {
            FormattedBytes::Plain(value) => write!(formatter, "{value}"),
            FormattedBytes::Unscaled(value) => write!(formatter, "{value}   "),
            FormattedBytes::Scaled(value, unit) => write!(formatter, "{value:.1}{unit}"),
        }
    }
}

impl BytesFormat {
    /// Format a number of bytes.
    pub fn format(self, value: u64) -> FormattedBytes {
        let base: u64 = match self {
            BytesFormat::Plain => return FormattedBytes::Plain(value),
            BytesFormat::Metric => 1000,
            BytesFormat::Binary => 1024,
        };
        if value < base {
            return FormattedBytes::Unscaled(value);
        }
        let mut divisor = base as f64;
        let mut unit = UNITS[0];
        let mut threshold = base;
        for &next_unit in UNITS.iter().skip(1) {
            match threshold.checked_mul(base) {
                Some(next_threshold) if value >= next_threshold => {
                    threshold = next_threshold;
                    divisor *= base as f64;
                    unit = next_unit;
                }
                _ => break,
            }
        }
        FormattedBytes::Scaled(value as f64 / divisor, unit)
    }
}
