//! In-memory representation of disk usage data.

pub mod reflection;
pub mod retain;

use std::ffi::OsString;

/// A node in the disk usage tree.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DataTree {
    /// Name of the entry (file name or the path given on the command line).
    pub name: OsString,
    /// Measured size of the whole subtree.
    pub size: u64,
    /// Direct descendants.
    pub children: Vec<DataTree>,
}

impl DataTree {
    /// Create a leaf node.
    pub fn leaf(name: OsString, size: u64) -> Self {
        DataTree {
            name,
            size,
            children: Vec::new(),
        }
    }

    /// Create a directory node whose size is its own size plus the sizes of its children.
    pub fn dir(name: OsString, own_size: u64, children: Vec<DataTree>) -> Self {
        let size = children
            .iter()
            .fold(own_size, |acc, child| acc.wrapping_add(child.size));
        DataTree {
            name,
            size,
            children,
        }
    }

    /// Sort all branches by size, biggest first. The sort is stable.
    pub fn sort_by_size_desc(&mut self) {
        self.children.sort_by(|a, b| b.size.cmp(&a.size));
        for child in &mut self.children {
            child.sort_by_size_desc();
        }
    }

    /// Remove all nodes whose depth is at least `max_depth` (the root has depth 0).
    pub fn cut_depth(&mut self, max_depth: u64) {
        if max_depth <= 1 {
            self.children.clear();
            return;
        }
        for child in &mut self.children {
            child.cut_depth(max_depth - 1);
        }
    }

    /// Count the number of nodes in the tree.
    pub fn len(&self) -> usize {
        1 + self.children.iter().map(DataTree::len).sum::<usize>()
    }
}
