//! Filtering of the disk usage tree.

use super::DataTree;

impl DataTree {
    /// Remove descendants that do not satisfy the predicate.
    /// Descendants of a removed node are also removed.
    pub fn retain<F>(&mut self, mut predicate: F)
    where
        F: FnMut(&DataTree) -> bool,
    {
        self.retain_inner(&mut predicate);
    }

    fn retain_inner<F>(&mut self, predicate: &mut F)
    where
        F: FnMut(&DataTree) -> bool,
    {
        self.children.retain(|child| predicate(child));
        for child in &mut self.children {
            child.retain_inner(predicate);
        }
    }

    /// Remove descendants whose size is less than `min_ratio` of the root's size.
    pub fn retain_min_ratio(&mut self, min_ratio: f32) {
        let total = self.size as f32;
        self.retain(|node| !((node.size as f32 / total) < min_ratio));
    }
}
