//! Conversion between the in-memory tree and its serializable form.

use super::DataTree;
use crate::size::Size;
use serde::{Deserialize, Serialize};
use std::{
    ffi::OsString,
    fmt::{self, Display, Formatter},
    path::PathBuf,
};

/// Serializable form of [`DataTree`].
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Reflection {
    pub name: String,
    pub size: u64,
    pub children: Vec<Reflection>,
}

/// Error that occurs when a name cannot be converted to UTF-8.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OsStringDisplay(pub OsString);

impl Display for OsStringDisplay {
    fn fmt(&self, formatter: &mut Formatter<'_>) -> fmt::Result {
        write!(formatter, "{:?}", self.0)
    }
}

/// Error that occurs when the input reflection does not describe a valid tree.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ConversionError {
    /// A child has a size greater than its parent.
    ExcessiveChildren {
        path: PathBuf,
        size: Size,
        child_name: String,
        child_size: Size,
    },
}

impl Display for ConversionError {
    fn fmt(&self, formatter: &mut Formatter<'_>) -> fmt::Result {
        match self {
            ConversionError::ExcessiveChildren {
                path,
                size,
                child_name,
                child_size,
            } => write!(
                formatter,
                "ExcessiveChildren: {path:?} ({size:?}) is less than a child named {child_name:?} ({child_size:?})",
            ),
        }
    }
}

impl DataTree {
    /// Convert into a serializable reflection.
    /// Fails if any name is not valid UTF-8.
    pub fn into_reflection(self) -> Result<Reflection, OsStringDisplay> {
        let DataTree {
            name,
            size,
            children,
        } = self;
        let name = name.into_string().map_err(OsStringDisplay)?;
        let children = children
            .into_iter()
            .map(DataTree::into_reflection)
            .collect::<Result<Vec<_>, _>>()?;
        Ok(Reflection {
            name,
            size,
            children,
        })
    }
}

impl Reflection {
    /// Validate the reflection and convert it into a tree.
    pub fn into_data_tree(self, bytes: bool) -> Result<DataTree, ConversionError> {
        self.validate(PathBuf::new(), bytes)?;
        Ok(self.into_data_tree_unchecked())
    }

    fn validate(&self, parent: PathBuf, bytes: bool) -> Result<(), ConversionError> {
        let path = parent.join(&self.name);
        for child in &self.children {
            if child.size > self.size {
                return Err(ConversionError::ExcessiveChildren {
                    path,
                    size: Size::new(self.size, bytes),
                    child_name: child.name.clone(),
                    child_size: Size::new(child.size, bytes),
                });
            }
        }
        for child in &self.children {
            child.validate(path.clone(), bytes)?;
        }
        Ok(())
    }

    fn into_data_tree_unchecked(self) -> DataTree {
        let Reflection {
            name,
            size,
            children,
        } = self;
        DataTree {
            name: OsString::from(name),
            size,
            children: children
                .into_iter()
                .map(Reflection::into_data_tree_unchecked)
                .collect(),
        }
    }
}
