//! Collection of files that have more than one hardlink.

pub mod summary;

use crate::data_tree::DataTree;
use serde::{Deserialize, Serialize};
use std::{
    collections::{BTreeMap, HashMap},
    path::{Path, PathBuf},
    sync::Mutex,
};

pub use summary::SharedSummary;

/// Information about a single inode with multiple links.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct HardlinkRecord {
    /// Inode number.
    pub ino: u64,
    /// Measured size of the file.
    pub size: u64,
    /// Number of links reported by the filesystem.
    pub links: u64,
    /// Paths of the links found during the scan (may contain duplicates).
    pub paths: Vec<PathBuf>,
}

impl HardlinkRecord {
    /// Number of links found during the scan.
    pub fn detected_links(&self) -> u64 {
        self.paths.len() as u64
    }

    /// Whether all links of the inode were found during the scan.
    pub fn is_exclusive(&self) -> bool {
        self.detected_links() >= self.links
    }
}

/// Serializable description of an inode with multiple links.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct SharedDetail {
    pub ino: u64,
    pub size: u64,
    pub links: u64,
    pub paths: Vec<String>,
}

/// Thread-safe list of hardlinks found during a scan.
#[derive(Debug, Default)]
pub struct HardlinkList {
    records: Mutex<BTreeMap<u64, HardlinkRecord>>,
}

impl HardlinkList {
    /// Create an empty list.
    pub fn new() -> Self {
        Self::default()
    }

    /// Record a link of an inode.
    pub fn add(&self, ino: u64, size: u64, links: u64, path: PathBuf) {
        let mut records = self.records.lock().expect("lock hardlink list");
        records
            .entry(ino)
            .or_insert_with(|| HardlinkRecord {
                ino,
                size,
                links,
                paths: Vec::new(),
            })
            .paths
            .push(path);
    }

    /// Take the records out, sorted by inode number.
    pub fn into_records(self) -> Vec<HardlinkRecord> {
        let records = self.records.into_inner().expect("unlock hardlink list");
        records.into_values().collect()
    }
}

/// Deduplicated and summarized hardlink information.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SharedInfo {
    pub records: Vec<HardlinkRecord>,
}

impl SharedInfo {
    /// Whether no hardlinks were found.
    pub fn is_empty(&self) -> bool {
        self.records.is_empty()
    }

    /// Produce the serializable details.
    pub fn details(&self) -> Vec<SharedDetail> {
        self.records
            .iter()
            .map(|record| {
                let mut paths: Vec<String> = Vec::new();
                for path in &record.paths {
                    let text = path.to_string_lossy().into_owned();
                    if !paths.contains(&text) {
                        paths.push(text);
                    }
                }
                SharedDetail {
                    ino: record.ino,
                    size: record.size,
                    links: record.links,
                    paths,
                }
            })
            .collect()
    }

    /// Produce the summary.
    pub fn summary(&self) -> SharedSummary {
        SharedSummary::from_records(&self.records)
    }

    /// Subtract the sizes of extra links from every node that contains them.
    ///
    /// `root_path` is the path of the root node, or `None` when the root is virtual
    /// (the `(total)` node that contains every argument).
    pub fn deduplicate(&self, tree: &mut DataTree, root_path: Option<&Path>) {
        let mut excess: HashMap<PathBuf, u64> = HashMap::new();
        let mut virtual_root_excess: u64 = 0;
        for record in &self.records {
            let mut counts: HashMap<&Path, u64> = HashMap::new();
            for path in &record.paths {
                for ancestor in path.ancestors() {
                    *counts.entry(ancestor).or_insert(0) += 1;
                }
            }
            for (path, count) in counts {
                if count > 1 {
                    let amount = record.size.wrapping_mul(count - 1);
                    let entry = excess.entry(path.to_path_buf()).or_insert(0);
                    *entry = entry.wrapping_add(amount);
                }
            }
            let total = record.detected_links();
            if total > 1 {
                virtual_root_excess =
                    virtual_root_excess.wrapping_add(record.size.wrapping_mul(total - 1));
            }
        }

        fn visit(node: &mut DataTree, path: PathBuf, excess: &HashMap<PathBuf, u64>) {
            if let Some(amount) = excess.get(&path) {
                node.size = node.size.wrapping_sub(*amount);
            }
            for child in &mut node.children {
                let child_path = path.join(&child.name);
                visit(child, child_path, excess);
            }
        }

        match root_path {
            Some(root_path) => visit(tree, root_path.to_path_buf(), &excess),
            None => {
                tree.size = tree.size.wrapping_sub(virtual_root_excess);
                for child in &mut tree.children {
                    let child_path = PathBuf::from(&child.name);
                    visit(child, child_path, &excess);
                }
            }
        }
    }
}
