//! Reporter that prints both progress and errors to stderr.

use super::{ErrorReport, Reporter};
use std::{
    io::{self, Write},
    sync::{
        atomic::{AtomicBool, AtomicU64, Ordering},
        Arc, Mutex,
    },
    thread::{self, JoinHandle},
    time::Duration,
};

/// Interval between two progress reports.
const INTERVAL: Duration = Duration::from_millis(100);

#[derive(Debug, Default)]
struct Progress {
    items: AtomicU64,
    total: AtomicU64,
    errors: AtomicU64,
}

impl Progress {
    fn text(&self) -> String {
        let items = self.items.load(Ordering::Relaxed);
        let total = self.total.load(Ordering::Relaxed);
        let errors = self.errors.load(Ordering::Relaxed);
        if errors == 0 {
            format!("(scanned {items}, total {total})")
        } else {
            format!("(scanned {items}, total {total}, erred {errors})")
        }
    }
}

/// Keeps track of what was last written so that it can be erased.
#[derive(Debug, Default)]
struct Line {
    width: usize,
}

impl Line {
    fn clear(&mut self, stderr: &mut io::StderrLock<'_>) {
        let _ = write!(stderr, "\r{:width$}\r", "", width = self.width);
        self.width = 0;
    }

    fn show(&mut self, stderr: &mut io::StderrLock<'_>, text: &str) {
        self.clear(stderr);
        let _ = write!(stderr, "\r{text}");
        self.width = text.len();
        let _ = stderr.flush();
    }

    fn message(&mut self, stderr: &mut io::StderrLock<'_>, text: &str) {
        self.clear(stderr);
        let _ = writeln!(stderr, "{text}");
        let _ = stderr.flush();
    }
}

#[derive(Debug, Default)]
struct Shared {
    progress: Progress,
    line: Mutex<Line>,
    done: AtomicBool,
}

/// Reporter that periodically prints progress to stderr.
#[derive(Debug)]
pub struct ProgressAndErrorReporter {
    shared: Arc<Shared>,
    silent_errors: bool,
    ticker: Option<JoinHandle<()>>,
}

impl ProgressAndErrorReporter {
    /// Start reporting progress.
    pub fn new(silent_errors: bool) -> Self {
        let shared = Arc::new(Shared::default());
        let ticker = {
            let shared = Arc::clone(&shared);
            thread::spawn(move || loop {
                thread::sleep(INTERVAL);
                if shared.done.load(Ordering::SeqCst) {
                    break;
                }
                let text = shared.progress.text();
                let stderr = io::stderr();
                let mut stderr = stderr.lock();
                let mut line = shared.line.lock().expect("lock progress line");
                line.show(&mut stderr, &text);
            })
        };
        ProgressAndErrorReporter {
            shared,
            silent_errors,
            ticker: Some(ticker),
        }
    }

    /// Stop reporting progress and erase the progress line.
    pub fn finish(mut self) {
        self.shared.done.store(true, Ordering::SeqCst);
        if let Some(ticker) = self.ticker.take() {
            let _ = ticker.join();
        }
        let stderr = io::stderr();
        let mut stderr = stderr.lock();
        let mut line = self.shared.line.lock().expect("lock progress line");
        line.clear(&mut stderr);
        let _ = stderr.flush();
    }
}

impl Reporter for ProgressAndErrorReporter {
    fn report_item(&self, size: u64) {
        self.shared.progress.items.fetch_add(1, Ordering::Relaxed);
        self.shared.progress.total.fetch_add(size, Ordering::Relaxed);
    }

    fn report_error(&self, report: ErrorReport<'_>) {
        self.shared.progress.errors.fetch_add(1, Ordering::Relaxed);
        if self.silent_errors {
            return;
        }
        let text = report.to_string();
        let stderr = io::stderr();
        let mut stderr = stderr.lock();
        let mut line = self.shared.line.lock().expect("lock progress line");
        line.message(&mut stderr, &text);
    }
}
EOF
