//! Drawing of proportion bars.

use super::tree::Row;

/// Side of the bar column that the bars grow from.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BarAlignment {
    Left,
    Right,
}

/// Divide and round to the nearest integer (halves are rounded up).
pub fn rounded_div(dividend: u64, divisor: u64) -> u64 {
    let quotient = dividend / divisor;
    let remainder = dividend % divisor;
    if remainder.wrapping_mul(2) >= divisor {
        quotient + 1
    } else {
        quotient
    }
}

/// Width of a portion of the bar.
fn portion(size: u64, bar_width: usize, total: u64) -> usize {
    if total == 0 {
        return 0;
    }
    let value = rounded_div(size.wrapping_mul(bar_width as u64), total);
    value as usize
}

fn shade(level: usize) -> char {
    match level {
        0 => ' ',
        1 => '░',
        2 => '▒',
        _ => '▓',
    }
}

/// Draw the bar of a row.
pub fn paint_bar(row: &Row, bar_width: usize, total: u64, alignment: BarAlignment) -> String {
    let mut cells = vec![' '; bar_width];
    for (index, &ancestor_size) in row.ancestor_sizes.iter().enumerate() {
        let level = index + 1;
        let width = portion(ancestor_size, bar_width, total).min(bar_width);
        for cell in cells.iter_mut().take(width) {
            *cell = shade(level);
        }
    }
    let width = portion(row.size, bar_width, total).min(bar_width);
    for cell in cells.iter_mut().take(width) {
        *cell = '█';
    }
    match alignment {
        BarAlignment::Left => cells.into_iter().collect(),
        BarAlignment::Right => cells.into_iter().rev().collect(),
    }
}
