cat > /workspace/src/visualizer/column_width.rs <<'EOF'
//! Distribution of the available width between the tree column and the bar column.

use super::tree::TreeRows;

/// Overhead of a line in addition to the size column, the tree column, and the bar column:
/// a space after the size, two borders around the bar, and the percentage.
const FIXED_OVERHEAD: usize = 1 + 2 + 4;

/// The size column and the bar column are expected to share this much space.
const SIZE_AND_BAR_BUDGET: usize = 10;

/// Width constraints of the chart.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ColumnWidthDistribution {
    /// Width of the whole chart.
    Total { width: usize },
    /// Maximum width of the tree column and exact width of the bar column.
    Components { tree_width: usize, bar_width: usize },
}

/// Result of fitting the rows into the available width.
#[derive(Debug)]
pub struct Layout {
    pub tree_width: usize,
    pub bar_width: usize,
    pub rows: TreeRows,
}

impl ColumnWidthDistribution {
    /// Compute the column widths and the rows that fit in them.
    ///
    /// `build_rows` creates the rows given the maximum width of the tree column.
    pub fn layout<F>(self, size_width: usize, mut build_rows: F) -> Option<Layout>
    where
        F: FnMut(usize) -> TreeRows,
    {
        match self {
            ColumnWidthDistribution::Components {
                tree_width,
                bar_width,
            } => {
                let rows = build_rows(tree_width);
                if rows.is_empty() {
                    return None;
                }
                Some(Layout {
                    tree_width: rows.max_width,
                    bar_width: bar_width.max(1),
                    rows,
                })
            }
            ColumnWidthDistribution::Total { width } => {
                let fixed = size_width + FIXED_OVERHEAD;
                let remaining = width.saturating_sub(fixed);
                let min_bar_width = SIZE_AND_BAR_BUDGET.saturating_sub(size_width);
                let tree_max = remaining.saturating_sub(min_bar_width);

                if tree_max == 0 {
                    // Not enough space for a sensible layout: fall back to fixed widths.
                    let rows = build_rows(fixed);
                    if rows.is_empty() {
                        return None;
                    }
                    let bar_width = if remaining == 0 { 3 } else { 20 };
                    return Some(Layout {
                        tree_width: rows.max_width,
                        bar_width,
                        rows,
                    });
                }

                let rows = build_rows(tree_max);
                if rows.is_empty() {
                    return None;
                }
                let bar_width = remaining.saturating_sub(rows.max_width);
                if bar_width == 0 {
                    // The bar would vanish: let the tree take whatever it needs.
                    let rows = build_rows(width);
                    if rows.is_empty() {
                        return None;
                    }
                    return Some(Layout {
                        tree_width: rows.max_width,
                        bar_width: 1,
                        rows,
                    });
                }
                Some(Layout {
                    tree_width: rows.max_width,
                    bar_width,
                    rows,
                })
            }
        }
    }
}
EOF
