//! Construction of the tree column.

use super::{width::display_width, Direction};
use crate::data_tree::DataTree;
use std::ffi::OsStr;

/// Width of the branch characters between the indentation and the name.
const BRANCH_WIDTH: usize = 3;

/// Width of each level of indentation.
const INDENT_WIDTH: usize = 2;

/// Marker appended to truncated names.
const ELLIPSIS: &str = "...";

/// A node of the tree after names have been truncated to fit the column.
#[derive(Debug, Clone, PartialEq, Eq)]
struct FittedNode {
    name: String,
    size: u64,
    width: usize,
    children: Vec<FittedNode>,
}

/// A single line of the tree column together with the data needed to draw its bar.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Row {
    /// Depth of the node, the root has depth 0.
    pub depth: usize,
    /// Displayed name, possibly truncated.
    pub name: String,
    /// Size of the node.
    pub size: u64,
    /// Width of the line in the tree column.
    pub width: usize,
    /// Sizes of the ancestors at depths `1..depth`.
    pub ancestor_sizes: Vec<u64>,
    /// Whether the ancestors at depths `1..depth` are the last of their siblings.
    pub ancestor_last: Vec<bool>,
    /// Whether the node is the last of its siblings.
    pub is_last: bool,
    /// Whether the node has displayed children.
    pub has_children: bool,
}

impl Row {
    /// Text of the tree column (without padding).
    pub fn tree_text(&self, direction: Direction) -> String {
        let mut text = String::new();
        if self.depth > 0 {
            text.push_str("  ");
            for &last in &self.ancestor_last {
                text.push_str(if last { "  " } else { "│ " });
            }
        }
        let (first, last_branch) = match direction {
            Direction::TopDown => (if self.depth == 0 || self.is_last { '└' } else { '├' }, '┬'),
            Direction::BottomUp => (if self.depth == 0 || self.is_last { '┌' } else { '├' }, '┴'),
        };
        text.push(first);
        text.push('─');
        text.push(if self.has_children { last_branch } else { '─' });
        text.push_str(&self.name);
        text
    }
}

/// All rows of the chart in top-down order.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TreeRows {
    pub rows: Vec<Row>,
    pub max_width: usize,
}

impl TreeRows {
    /// Whether nothing fits.
    pub fn is_empty(&self) -> bool {
        self.rows.is_empty()
    }

    /// Fit the tree into a column of at most `max_width` cells.
    pub fn build(tree: &DataTree, max_width: usize) -> Self {
        let mut rows = Vec::new();
        if let Some(fitted) = fit(tree, 0, max_width) {
            flatten(&fitted, 0, true, &mut Vec::new(), &mut Vec::new(), &mut rows);
        }
        let max_width = rows.iter().map(|row| row.width).max().unwrap_or(0);
        TreeRows { rows, max_width }
    }
}

/// Human-readable form of a file name.
pub fn display_name(name: &OsStr) -> String {
    match name.to_str() {
        Some(text) => text.to_string(),
        None => format!("{name:?}"),
    }
}

/// Fit a node and its descendants into the column, dropping what does not fit.
fn fit(node: &DataTree, depth: usize, max_width: usize) -> Option<FittedNode> {
    let indent = depth * INDENT_WIDTH;
    let mut name = display_name(&node.name);
    let full_width = indent + BRANCH_WIDTH + display_width(&name);
    let width = if full_width <= max_width {
        full_width
    } else {
        let name_max = max_width.checked_sub(indent + BRANCH_WIDTH)?;
        let new_len = name_max.checked_sub(ELLIPSIS.len())?;
        if new_len == 0 {
            return None;
        }
        truncate(&mut name, new_len);
        name.push_str(ELLIPSIS);
        max_width
    };
    let children = node
        .children
        .iter()
        .filter_map(|child| fit(child, depth + 1, max_width))
        .collect();
    Some(FittedNode {
        name,
        size: node.size,
        width,
        children,
    })
}

/// Shorten a name to `new_len` bytes.
fn truncate(name: &mut String, new_len: usize) {
    if name.len() > new_len {
        name.truncate(new_len);
    }
}

fn flatten(
    node: &FittedNode,
    depth: usize,
    is_last: bool,
    ancestor_sizes: &mut Vec<u64>,
    ancestor_last: &mut Vec<bool>,
    rows: &mut Vec<Row>,
) {
    rows.push(Row {
        depth,
        name: node.name.clone(),
        size: node.size,
        width: node.width,
        ancestor_sizes: ancestor_sizes.clone(),
        ancestor_last: ancestor_last.clone(),
        is_last,
        has_children: !node.children.is_empty(),
    });
    if depth > 0 {
        ancestor_sizes.push(node.size);
        ancestor_last.push(is_last);
    }
    let count = node.children.len();
    for (index, child) in node.children.iter().enumerate() {
        flatten(
            child,
            depth + 1,
            index + 1 == count,
            ancestor_sizes,
            ancestor_last,
            rows,
        );
    }
    if depth > 0 {
        ancestor_sizes.pop();
        ancestor_last.pop();
    }
}
