//! Construction of the disk usage tree from the filesystem.

use crate::{
    args::quantity::Quantity,
    data_tree::DataTree,
    hardlink::HardlinkList,
    reporter::{ErrorReport, Operation, Reporter},
};
use rayon::prelude::*;
use std::{
    ffi::OsString,
    fs::{self, Metadata},
    os::unix::fs::MetadataExt,
    path::{Path, PathBuf},
};

impl Quantity {
    /// Measure a filesystem entry.
    pub fn measure(self, metadata: &Metadata) -> u64 {
        match self {
            Quantity::ApparentSize => metadata.len(),
            Quantity::BlockSize => metadata.blocks().wrapping_mul(512),
            Quantity::BlockCount => metadata.blocks(),
        }
    }
}

/// Builds disk usage trees by walking the filesystem in parallel.
#[derive(Clone, Copy)]
pub struct FsTreeBuilder<'a> {
    /// What to measure.
    pub quantity: Quantity,
    /// Where to send errors and progress.
    pub reporter: &'a dyn Reporter,
    /// Where to record hardlinks, if they are to be detected.
    pub hardlinks: Option<&'a HardlinkList>,
}

impl FsTreeBuilder<'_> {
    /// Build the tree rooted at `path`, naming the root `name`.
    pub fn build(&self, path: PathBuf, name: OsString) -> DataTree {
        let metadata = match fs::symlink_metadata(&path) {
            Ok(metadata) => metadata,
            Err(error) => {
                self.reporter.report_error(ErrorReport {
                    operation: Operation::SymlinkMetadata,
                    path: &path,
                    error,
                });
                return DataTree::leaf(name, 0);
            }
        };
        let size = self.quantity.measure(&metadata);

        if !metadata.is_dir() {
            if let Some(hardlinks) = self.hardlinks {
                if metadata.nlink() > 1 {
                    hardlinks.add(metadata.ino(), size, metadata.nlink(), path);
                }
            }
            self.reporter.report_item(size);
            return DataTree::leaf(name, size);
        }

        let entries = match self.read_dir(&path) {
            Some(entries) => entries,
            None => return DataTree::leaf(name, 0),
        };
        self.reporter.report_item(size);
        let children: Vec<DataTree> = entries
            .into_par_iter()
            .map(|child_name| {
                let child_path = path.join(&child_name);
                self.build(child_path, child_name)
            })
            .collect();
        DataTree::dir(name, size, children)
    }

    /// List the names of the entries of a directory.
    fn read_dir(&self, path: &Path) -> Option<Vec<OsString>> {
        let read_dir = match fs::read_dir(path) {
            Ok(read_dir) => read_dir,
            Err(error) => {
                self.reporter.report_error(ErrorReport {
                    operation: Operation::ReadDir,
                    path,
                    error,
                });
                return None;
            }
        };
        let mut names = Vec::new();
        for entry in read_dir {
            match entry {
                Ok(entry) => names.push(entry.file_name()),
                Err(error) => self.reporter.report_error(ErrorReport {
                    operation: Operation::AccessEntry,
                    path,
                    error,
                }),
            }
        }
        Some(names)
    }
}
