//! The application: glue between the command-line arguments and the library.

pub mod overlapping_arguments;
pub mod sub;
pub mod terminal;

use crate::{
    args::{threads::Threads, Args},
    data_tree::reflection::ConversionError,
};
use std::fmt::{self, Display, Formatter};

/// Errors that end the program with a non-zero exit code.
#[derive(Debug)]
pub enum RuntimeError {
    /// Positional arguments were given together with `--json-input`.
    JsonInputArgConflict,
    /// The JSON input could not be parsed.
    DeserializationFailure(serde_json::Error),
    /// The JSON output could not be produced.
    SerializationFailure(serde_json::Error),
    /// The JSON input describes an invalid tree.
    InvalidInputReflection(ConversionError),
}

impl RuntimeError {
    /// Exit code of the process.
    pub fn code(&self) -> i32 {
        match self {
            RuntimeError::SerializationFailure(_) => 2,
            RuntimeError::DeserializationFailure(_) => 3,
            RuntimeError::JsonInputArgConflict => 4,
            RuntimeError::InvalidInputReflection(_) => 5,
        }
    }
}

impl Display for RuntimeError {
    fn fmt(&self, formatter: &mut Formatter<'_>) -> fmt::Result {
        match self {
            RuntimeError::JsonInputArgConflict => {
                write!(formatter, "JsonInputArgConflict: Arguments exist alongside --json-input")
            }
            RuntimeError::DeserializationFailure(error) => {
                write!(formatter, "DeserializationFailure: {error}")
            }
            RuntimeError::SerializationFailure(error) => {
                write!(formatter, "SerializationFailure: {error}")
            }
            RuntimeError::InvalidInputReflection(error) => {
                write!(formatter, "InvalidInputReflection: {error}")
            }
        }
    }
}

/// Configure the global thread pool.
fn configure_threads(threads: Threads) {
    let num_threads = match threads {
        Threads::Auto => return,
        Threads::Max => std::thread::available_parallelism()
            .map(|value| value.get())
            .unwrap_or(1),
        Threads::Fixed(value) => value.get(),
    };
    let _ = rayon::ThreadPoolBuilder::new()
        .num_threads(num_threads)
        .build_global();
}

/// Run the application.
pub fn run(args: Args) -> Result<(), RuntimeError> {
    if args.json_input {
        return sub::json_input(args);
    }
    configure_threads(args.threads);
    sub::filesystem(args)
}
