//! Terminal queries.

use std::mem::MaybeUninit;

/// Width that is assumed when the terminal width cannot be determined.
pub const DEFAULT_WIDTH: usize = 150;

/// Query the number of columns of the terminal attached to a file descriptor.
fn columns_of(fd: libc::c_int) -> Option<usize> {
    let mut size = MaybeUninit::<libc::winsize>::uninit();
    // SAFETY: TIOCGWINSZ writes a `winsize` into the provided pointer.
    let result = unsafe { libc::ioctl(fd, libc::TIOCGWINSZ, size.as_mut_ptr()) };
    if result != 0 {
        return None;
    }
    // SAFETY: the ioctl succeeded, so the structure has been initialized.
    let size = unsafe { size.assume_init() };
    if size.ws_col == 0 {
        None
    } else {
        Some(size.ws_col as usize)
    }
}

/// Width of the terminal, if any of the standard streams is attached to one.
pub fn width() -> Option<usize> {
    [libc::STDOUT_FILENO, libc::STDIN_FILENO, libc::STDERR_FILENO]
        .into_iter()
        .find_map(columns_of)
}
