//! Removal of directory arguments that are contained in other directory arguments.

use std::{
    fs,
    path::{Path, PathBuf},
};

/// Canonical path of a directory argument, `None` for anything that is not a directory.
fn canonical_dir(path: &Path) -> Option<PathBuf> {
    let metadata = fs::symlink_metadata(path).ok()?;
    if !metadata.is_dir() {
        return None;
    }
    fs::canonicalize(path).ok()
}

/// Remove directories that are the same as or inside another directory in the list.
/// When two directories are the same, the first one is kept.
pub fn remove_overlapping_dirs(files: Vec<PathBuf>) -> Vec<PathBuf> {
    let canonical: Vec<Option<PathBuf>> = files.iter().map(|path| canonical_dir(path)).collect();
    files
        .into_iter()
        .enumerate()
        .filter(|(index, _)| {
            let Some(this) = &canonical[*index] else {
                return true;
            };
            let covered = canonical.iter().enumerate().any(|(other_index, other)| {
                if other_index == *index {
                    return false;
                }
                let Some(other) = other else {
                    return false;
                };
                if this == other {
                    other_index < *index
                } else {
                    this.starts_with(other)
                }
            });
            !covered
        })
        .map(|(_, path)| path)
        .collect()
}
