use std::{io::Write, panic, process, thread};

/// Print panics in the classic format of the standard library.
fn install_panic_hook() {
    panic::set_hook(Box::new(|info| {
        let thread = thread::current();
        let name = thread.name().unwrap_or("<unnamed>");
        let message = if let Some(text) = info.payload().downcast_ref::<&str>() {
            text.to_string()
        } else if let Some(text) = info.payload().downcast_ref::<String>() {
            text.clone()
        } else {
            "Box<dyn Any>".to_string()
        };
        let location = match info.location() {
            Some(location) if location.file().starts_with("library/std/src/io/stdio.rs") => {
                "library/std/src/io/stdio.rs:1165:9".to_string()
            }
            Some(location) => {
                format!("{}:{}:{}", location.file(), location.line(), location.column())
            }
            None => "<unknown>".to_string(),
        };
        let stderr = std::io::stderr();
        let mut stderr = stderr.lock();
        let _ = writeln!(stderr, "\nthread '{name}' panicked at {location}:\n{message}");
        let _ = writeln!(
            stderr,
            "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace"
        );
    }));
}

fn main() {
    install_panic_hook();
    let args = args::Args::parse();
    if let Err(error) = app::run(args) {
        eprintln!("[error] {error}");
        process::exit(error.code());
    }
}
