const UNITS: [char; 5] = ['K', 'M', 'G', 'T', 'P'];
fn fmt_a(value: u64, base: u64) -> String { // f64 single division
    if value < base { return format!("{value}"); }
    let mut div = base as f64; let mut unit = 0;
    let mut t = base;
    for i in 1..5 { match t.checked_mul(base) { Some(n) if value >= n => { t = n; div *= base as f64; unit = i; } _ => break } }
    format!("{:.1}{}", value as f64 / div, UNITS[unit])
}
fn fmt_b(value: u64, base: u64) -> String { // f32 single division, value as f32
    if value < base { return format!("{value}"); }
    let mut div = base as f32; let mut unit = 0;
    let mut t = base;
    for i in 1..5 { match t.checked_mul(base) { Some(n) if value >= n => { t = n; div *= base as f32; unit = i; } _ => break } }
    format!("{:.1}{}", value as f32 / div, UNITS[unit])
}
fn fmt_c(value: u64, base: u64) -> String { // f32 repeated division
    if value < base { return format!("{value}"); }
    let mut v = value as f32; let mut unit = 0usize;
    let b = base as f32;
    loop { if v >= b && unit < 5 { v /= b; unit += 1; } else { break } }
    // unit index unit-1
    format!("{:.1}{}", v, UNITS[unit-1])
}
fn fmt_d(value: u64, base: u64) -> String { // f64 computation then cast to f32
    if value < base { return format!("{value}"); }
    let mut div = base as f64; let mut unit = 0;
    let mut t = base;
    for i in 1..5 { match t.checked_mul(base) { Some(n) if value >= n => { t = n; div *= base as f64; unit = i; } _ => break } }
    format!("{:.1}{}", (value as f64 / div) as f32, UNITS[unit])
}
fn fmt_e(value: u64, base: u64) -> String { // f32 with threshold check done in f32 domain (v >= 1000 after division)
    if value < base { return format!("{value}"); }
    let b = base as f32;
    let mut v = value as f32 / b; let mut unit = 0usize;
    while v >= b && unit < 4 { v /= b; unit += 1; }
    format!("{:.1}{}", v, UNITS[unit])
}
fn main() {
    let sizes: Vec<u64> = fs::read_to_string("/tmp/fmt/sizes.txt").unwrap().lines().map(|l| l.parse().unwrap()).collect();
    for (base, file) in [(1000u64, "/tmp/fmt/orig_metric.txt"), (1024, "/tmp/fmt/orig_binary.txt")] {
        let orig: Vec<String> = fs::read_to_string(file).unwrap().lines().map(|l| l.to_string()).collect();
        assert_eq!(orig.len(), sizes.len());
        let mut bad = [0usize; 5];
        for (i, &s) in sizes.iter().enumerate() {
            let cands = [fmt_a(s, base), fmt_b(s, base), fmt_c(s, base), fmt_d(s, base), fmt_e(s, base)];
            for (k, c) in cands.iter().enumerate() { if *c != orig[i] { bad[k] += 1; if bad[k] <= 3 { println!("base {base} cand {k}: size {s} orig {} mine {}", orig[i], c); } } }
        }
        println!("base {base}: mismatches a={} b={} c={} d={} e={}", bad[0], bad[1], bad[2], bad[3], bad[4]);
    }
}
